package com.bank.spark.model;

// An executor's idle status and whether it still holds needed shuffle files.
public class ExecutorState {
    private final int id;
    private boolean idle;
    private boolean holdsNeededShuffle;

    public ExecutorState(int id, boolean idle, boolean holdsNeededShuffle) {
        this.id = id;
        this.idle = idle;
        this.holdsNeededShuffle = holdsNeededShuffle;
    }

    public int getId() { return id; }
    public boolean isIdle() { return idle; }
    public boolean holdsNeededShuffle() { return holdsNeededShuffle; }
}
