package com.bank.spark.service;

import com.bank.spark.model.ExecutorState;
import java.util.List;
import java.util.logging.Logger;

// Scales executors up on backlog and down on idle, respecting shuffle safety.
public class ExecutorScaler {

    private static final Logger log = Logger.getLogger(ExecutorScaler.class.getName());

    private final int minExecutors;
    private final int maxExecutors;
    private final boolean externalShuffleService;
    private int current;

    public ExecutorScaler(int minExecutors, int maxExecutors,
                          boolean externalShuffleService, int initial) {
        this.minExecutors = minExecutors;
        this.maxExecutors = maxExecutors;
        this.externalShuffleService = externalShuffleService;
        this.current = initial;
    }

    // Scale up when there is a pending-task backlog.
    public void onBacklog(int pendingTasks) {
        if (pendingTasks > 0 && current < maxExecutors) {
            int add = Math.min(current, maxExecutors - current); // exponential-ish ramp
            current += add;
            log.info(() -> "Backlog " + pendingTasks + " → scaled UP to " + current + " executors");
        }
    }

    // Try to release idle executors; never drop one holding needed shuffle
    // unless the external shuffle service preserves its files.
    public void releaseIdle(List<ExecutorState> executors) {
        for (ExecutorState e : executors) {
            if (!e.isIdle() || current <= minExecutors) continue;
            if (e.holdsNeededShuffle() && !externalShuffleService) {
                log.warning(() -> "Executor " + e.getId()
                        + " idle but holds needed shuffle; NO shuffle service → KEEP");
                continue;
            }
            current--;
            log.info(() -> "Executor " + e.getId() + " released (idle" 
                    + (e.holdsNeededShuffle() ? ", shuffle preserved by service" : "")
                    + ") → " + current + " executors");
        }
    }

    public int getCurrent() { return current; }
}
