package com.bank.spark;

import com.bank.spark.model.ExecutorState;
import com.bank.spark.service.ExecutorScaler;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: scale up on backlog; release idle; keep shuffle-holder if no service.
public class DynamicAllocationDemo {

    private static final Logger log = Logger.getLogger(DynamicAllocationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // WITH external shuffle service: safe to remove shuffle holders.
        ExecutorScaler withService = new ExecutorScaler(2, 20, true, 2);
        log.info("--- WITH external shuffle service ---");
        withService.onBacklog(500);                 // heavy aggregation arrives
        withService.onBacklog(500);
        withService.releaseIdle(List.of(
            new ExecutorState(1, true, true),        // idle, holds shuffle → safe
            new ExecutorState(2, true, false),       // idle, no shuffle → safe
            new ExecutorState(3, false, false)));    // busy → keep

        // WITHOUT shuffle service: cannot remove a shuffle holder.
        ExecutorScaler noService = new ExecutorScaler(2, 20, false, 6);
        log.info("--- WITHOUT external shuffle service ---");
        noService.releaseIdle(List.of(
            new ExecutorState(4, true, true),        // idle but holds shuffle → KEEP
            new ExecutorState(5, true, false)));     // idle, no shuffle → release

        log.info("Dynamic allocation demo complete.");
    }
}
